CREATE TYPE "PaymentMethod" AS ENUM ('COD', 'MIDTRANS');
CREATE TYPE "PaymentStatus" AS ENUM ('pending', 'paid', 'failed', 'expired', 'cancelled', 'refunded');
CREATE TYPE "FulfillmentStatus" AS ENUM ('pending', 'confirmed', 'processing', 'ready-for-pickup', 'picked-up', 'on-delivery', 'delivered', 'completed', 'cancelled');
CREATE TYPE "ReservationStatus" AS ENUM ('reserved', 'released', 'consumed');
CREATE TABLE "carts" ("id" UUID NOT NULL, "customer_user_id" UUID NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "carts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "cart_items" ("id" UUID NOT NULL, "cart_id" UUID NOT NULL, "product_id" UUID NOT NULL, "product_variant_id" UUID, "quantity" INTEGER NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "cart_items_pkey" PRIMARY KEY ("id"), CONSTRAINT "cart_items_quantity_check" CHECK ("quantity" >= 1));
CREATE TABLE "checkout_transactions" ("id" UUID NOT NULL, "customer_user_id" UUID NOT NULL, "idempotency_key" VARCHAR(100) NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "checkout_transactions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "commerce_orders" ("id" UUID NOT NULL, "order_code" VARCHAR(40) NOT NULL, "checkout_transaction_id" UUID NOT NULL, "customer_user_id" UUID NOT NULL, "store_id" UUID NOT NULL, "fulfillment_status" "FulfillmentStatus" NOT NULL DEFAULT 'pending', "payment_status" "PaymentStatus" NOT NULL DEFAULT 'pending', "payment_method" "PaymentMethod" NOT NULL, "product_total" DECIMAL(14,2) NOT NULL, "delivery_fee" DECIMAL(14,2) NOT NULL, "courier_tip" DECIMAL(14,2) NOT NULL, "total_amount" DECIMAL(14,2) NOT NULL, "distance_km" DECIMAL(10,3) NOT NULL, "rounded_distance_km" INTEGER NOT NULL, "delivery_rate_snapshot" DECIMAL(14,2) NOT NULL, "recipient_name" VARCHAR(120) NOT NULL, "recipient_phone" VARCHAR(20) NOT NULL, "delivery_address" VARCHAR(1000) NOT NULL, "delivery_location" JSONB, "cancellation_reason" VARCHAR(1000), "payment_paid_at" TIMESTAMPTZ(3), "cancelled_at" TIMESTAMPTZ(3), "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "commerce_orders_pkey" PRIMARY KEY ("id"));
CREATE TABLE "commerce_order_items" ("id" UUID NOT NULL, "order_id" UUID NOT NULL, "product_id" UUID NOT NULL, "product_variant_id" UUID, "product_name" VARCHAR(180) NOT NULL, "variant_options" JSONB, "sku" VARCHAR(100), "image_url" VARCHAR(2000), "store_name" VARCHAR(160) NOT NULL, "unit_price" DECIMAL(14,2) NOT NULL, "quantity" INTEGER NOT NULL, "subtotal" DECIMAL(14,2) NOT NULL, CONSTRAINT "commerce_order_items_pkey" PRIMARY KEY ("id"), CONSTRAINT "commerce_order_items_quantity_check" CHECK ("quantity" >= 1));
CREATE TABLE "commerce_order_activities" ("id" UUID NOT NULL, "order_id" UUID NOT NULL, "actor_user_id" UUID, "actor_type" VARCHAR(32) NOT NULL, "activity_type" VARCHAR(80) NOT NULL, "from_status" VARCHAR(40), "to_status" VARCHAR(40), "description" TEXT NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "commerce_order_activities_pkey" PRIMARY KEY ("id"));
CREATE TABLE "stock_reservations" ("id" UUID NOT NULL, "order_id" UUID NOT NULL, "product_id" UUID NOT NULL, "product_variant_id" UUID, "quantity" INTEGER NOT NULL, "status" "ReservationStatus" NOT NULL DEFAULT 'reserved', "reserved_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expires_at" TIMESTAMPTZ(3), "released_at" TIMESTAMPTZ(3), "consumed_at" TIMESTAMPTZ(3), CONSTRAINT "stock_reservations_pkey" PRIMARY KEY ("id"), CONSTRAINT "stock_reservations_quantity_check" CHECK ("quantity" >= 1));
CREATE TABLE "payment_attempts" ("id" UUID NOT NULL, "order_id" UUID NOT NULL, "provider" VARCHAR(32) NOT NULL, "provider_reference" VARCHAR(100), "payment_method" "PaymentMethod" NOT NULL, "status" "PaymentStatus" NOT NULL DEFAULT 'pending', "amount" DECIMAL(14,2) NOT NULL, "provider_transaction_id" VARCHAR(100), "payment_type" VARCHAR(80), "paid_at" TIMESTAMPTZ(3), "expires_at" TIMESTAMPTZ(3), "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "payment_attempts_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "carts_customer_user_id_key" ON "carts"("customer_user_id"); CREATE INDEX "cart_items_cart_id_idx" ON "cart_items"("cart_id"); CREATE INDEX "cart_items_product_id_idx" ON "cart_items"("product_id");
CREATE UNIQUE INDEX "checkout_transactions_customer_user_id_idempotency_key_key" ON "checkout_transactions"("customer_user_id","idempotency_key");
CREATE UNIQUE INDEX "commerce_orders_order_code_key" ON "commerce_orders"("order_code"); CREATE INDEX "commerce_orders_customer_user_id_idx" ON "commerce_orders"("customer_user_id"); CREATE INDEX "commerce_orders_store_id_idx" ON "commerce_orders"("store_id"); CREATE INDEX "commerce_order_items_order_id_idx" ON "commerce_order_items"("order_id"); CREATE INDEX "commerce_order_activities_order_id_created_at_idx" ON "commerce_order_activities"("order_id","created_at"); CREATE INDEX "stock_reservations_order_id_idx" ON "stock_reservations"("order_id"); CREATE INDEX "stock_reservations_status_expires_at_idx" ON "stock_reservations"("status","expires_at"); CREATE UNIQUE INDEX "payment_attempts_provider_reference_key" ON "payment_attempts"("provider_reference"); CREATE INDEX "payment_attempts_order_id_idx" ON "payment_attempts"("order_id");
ALTER TABLE "carts" ADD CONSTRAINT "carts_customer_user_id_fkey" FOREIGN KEY ("customer_user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_cart_id_fkey" FOREIGN KEY ("cart_id") REFERENCES "carts"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_product_variant_id_fkey" FOREIGN KEY ("product_variant_id") REFERENCES "product_variants"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "checkout_transactions" ADD CONSTRAINT "checkout_transactions_customer_user_id_fkey" FOREIGN KEY ("customer_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "commerce_orders" ADD CONSTRAINT "commerce_orders_checkout_transaction_id_fkey" FOREIGN KEY ("checkout_transaction_id") REFERENCES "checkout_transactions"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "commerce_orders" ADD CONSTRAINT "commerce_orders_customer_user_id_fkey" FOREIGN KEY ("customer_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "commerce_orders" ADD CONSTRAINT "commerce_orders_store_id_fkey" FOREIGN KEY ("store_id") REFERENCES "stores"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "commerce_order_items" ADD CONSTRAINT "commerce_order_items_order_id_fkey" FOREIGN KEY ("order_id") REFERENCES "commerce_orders"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "commerce_order_items" ADD CONSTRAINT "commerce_order_items_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "commerce_order_items" ADD CONSTRAINT "commerce_order_items_product_variant_id_fkey" FOREIGN KEY ("product_variant_id") REFERENCES "product_variants"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "commerce_order_activities" ADD CONSTRAINT "commerce_order_activities_order_id_fkey" FOREIGN KEY ("order_id") REFERENCES "commerce_orders"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "stock_reservations" ADD CONSTRAINT "stock_reservations_order_id_fkey" FOREIGN KEY ("order_id") REFERENCES "commerce_orders"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "stock_reservations" ADD CONSTRAINT "stock_reservations_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "stock_reservations" ADD CONSTRAINT "stock_reservations_product_variant_id_fkey" FOREIGN KEY ("product_variant_id") REFERENCES "product_variants"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "payment_attempts" ADD CONSTRAINT "payment_attempts_order_id_fkey" FOREIGN KEY ("order_id") REFERENCES "commerce_orders"("id") ON DELETE CASCADE ON UPDATE CASCADE;
